ext('c12_eng_ch21',[
C("✍️","कमला दास का परिचय",["केरल की कवयित्री","अंग्रेज़ी में कमला दास, मलयालम में माधवीकुट्टी","आत्मकथा: माई स्टोरी","स्पष्टवादी और भावुक लेखन"],"कवयित्री कमला दास का जन्म केरल में हुआ। वे अंग्रेज़ी में कमला दास के नाम से और मलयालम में माधवीकुट्टी के नाम से लिखती थीं। उनकी आत्मकथा माई स्टोरी बहुत चर्चित रही। उनकी कविताओं की ख़ासियत है कि वे बहुत सच्चे और खुले ढंग से अपनी भावनाएँ लिखती थीं। भारतीय अंग्रेज़ी कविता में उन्हें एक महत्वपूर्ण स्थान प्राप्त है। उनकी रचनाओं में बचपन, प्रेम, अकेलापन और स्त्री के अनुभव प्रमुखता से आते हैं। परीक्षा में कवयित्री का नाम, राज्य और दोनों नाम याद रखिए।"),
C("🏠","दादी का घर: एक भावनात्मक स्थान",["बचपन की छुट्टियाँ वहीं बीतीं","प्रेम और सुरक्षा का स्थान","मिठास और अपनापन","अब बंद और सूना"],"कविता का केंद्र दादी का घर है। यह वह घर है जहाँ कवयित्री ने बचपन में प्रेम और सुरक्षा का अनुभव किया। वहाँ हर कोने में अपनापन था और दादी की गोद में बच्चे को कोई डर नहीं लगता था। आज वह घर बंद है और दादी इस दुनिया में नहीं हैं। कवयित्री के लिए वह घर सिर्फ़ ईंट-पत्थर की इमारत नहीं, बल्कि प्रेम की जगह था। इसी कारण उसके खो जाने का दुख बहुत गहरा है। हम सबके पास भी ऐसा कोई घर या कोना होता है जो यादों से भरा हो।"),
C("🌑","घर का सूनापन",["अँधेरा और ठंडापन","साँपों जैसी चुप्पी का बिंब","आवाज़ों का न होना","प्रेम के जाने से घर बदल गया"],"कविता में दादी के जाने के बाद घर का जो वर्णन है, वह बहुत उदास कर देता है। घर में अँधेरा है, ठंडक है और चारों ओर चुप्पी है। कवयित्री इस चुप्पी के लिए ऐसे बिंब चुनती हैं जो मन में सिहरन पैदा करते हैं। जहाँ पहले हँसी और बातचीत की आवाज़ें थीं, वहाँ अब सन्नाटा है। यहाँ बताया गया है कि घर को घर प्रेम बनाता है। जब प्रेम करने वाला व्यक्ति चला जाता है, तो वही घर पराया सा लगने लगता है। यह भाव पाठक के मन को भीतर तक छू जाता है।"),
C("🚪","अजनबियों के दरवाज़े पर प्रेम की भीख",["वर्तमान में प्रेम की कमी","अजनबियों से अपनापन ढूँढ़ना","भीख का रूपक","अधूरी तलाश"],"कविता का सबसे मार्मिक भाग वह है जहाँ कवयित्री कहती हैं कि अब वे अजनबियों के दरवाज़ों पर प्रेम माँगती फिरती हैं। यहाँ प्रेम की तुलना भीख से की गई है। यह दिखाता है कि जो प्रेम दादी के पास सहज और बिना माँगे मिलता था, वह अब कहीं और नहीं मिलता। वे प्रेम की तलाश में भटकती हैं पर संतोष नहीं पातीं। यह निःस्वार्थ प्रेम की क़ीमत को समझाता है। जिन्हें यह प्रेम सहज मिल रहा है, उन्हें इसकी क़द्र करनी चाहिए, क्योंकि खो जाने के बाद इसकी कमी सबसे ज़्यादा खलती है।"),
C("🕰️","स्मृति का स्वर",["वर्तमान से अतीत में जाना","तुलना: तब और अब","मन में अकेलापन","भावनाओं की सच्चाई"],"यह कविता स्मृति के स्वर में लिखी गई है। कवयित्री वर्तमान में खड़ी होकर अतीत को याद करती हैं और तब और अब की तुलना करती हैं। तब प्रेम था, अब ख़ालीपन है। तब घर में रोशनी थी, अब अँधेरा। इस तुलना से कविता में दर्द उभरता है। स्मृति कविता का मुख्य साधन है, क्योंकि वही अतीत और वर्तमान के बीच पुल बनाती है। अंग्रेज़ी साहित्य में इसे नॉस्टैल्जिया कहते हैं, यानी बीते हुए समय के लिए एक मीठी, पर दर्द भरी याद।"),
C("🪞","कविता का आत्मकथात्मक पहलू",["कवयित्री के अपने जीवन से जुड़ी","पहले पुरुष में कथन","अंतरंग और सच्ची भावना","पाठक से सीधा रिश्ता"],"कमला दास की अधिकतर कविताएँ उनके अपने जीवन से जुड़ी हैं, इसलिए उन्हें आत्मकथात्मक कहा जाता है। इस कविता में भी वे प्रथम पुरुष यानी मैं के रूप में अपनी बात कहती हैं। ऐसा कथन पाठक को सीधा जोड़ता है, क्योंकि वह सुनने वाले को अपनी निजी बात बताने जैसा लगता है। कविता में सच्चाई की जो गर्माहट है, वह इसी कारण पैदा होती है। इसलिए यह कविता केवल शब्दों का संयोजन नहीं, बल्कि एक सच्चे दिल की आवाज़ लगती है।"),
C("🎨","बिंब और प्रतीक",["अँधेरा: अकेलापन","चुप्पी: प्रेम का अभाव","बंद दरवाज़ा: बीते हुए रिश्ते","भीख: प्रेम की कमी"],"कविता में प्रतीकों का सुंदर प्रयोग है। अँधेरा अकेलेपन का, चुप्पी प्रेम के अभाव का, बंद दरवाज़ा बीते हुए रिश्तों का और भीख प्रेम की कमी का प्रतीक है। ये प्रतीक सीधे बताने की जगह भाव को बिंबों के रूप में सामने रखते हैं, जिससे कविता ज़्यादा प्रभावशाली बनती है। जब आप परीक्षा में काव्य सौंदर्य लिखें, तो इन प्रतीकों का उल्लेख ज़रूर करें और हर एक का अर्थ लिखें। इससे आपका उत्तर बहुत मज़बूत दिखेगा।"),
C("👵","दादी-नानी का महत्व",["निःस्वार्थ स्नेह","कहानियाँ और संस्कार","अनुभव की पूँजी","उन्हें समय देना"],"यह कविता हमें अपने बुज़ुर्गों के महत्व की याद दिलाती है। दादी-नानी बिना किसी स्वार्थ के प्रेम देती हैं। वे हमें कहानियाँ, संस्कार और जीवन का अनुभव सौंपती हैं। हमारे बिहार के हर घर में दादी की गोद में सुनी कहानियाँ और उनके बनाए पकवान बचपन की सबसे मीठी याद होते हैं। फिर भी कई बार हम व्यस्तता में उन्हें समय नहीं दे पाते। कविता सिखाती है कि जब तक वे हमारे साथ हैं, तब तक उनके पास बैठिए, उनकी बातें सुनिए और उन्हें ख़ुशी दीजिए।"),
C("📝","शब्दार्थ दोहराइए",["नॉस्टैल्जिया यानी बीते की याद","ड्वेलिंग यानी निवास","लोनलीनेस यानी अकेलापन","बेग यानी भीख माँगना"],"कुछ शब्द दोहराइए। नॉस्टैल्जिया यानी बीते समय की याद, लोनलीनेस यानी अकेलापन, बेग यानी याचना या भीख माँगना, सायलेंस यानी चुप्पी, और ग्रैंडमदर यानी दादी। साथ में लव यानी प्रेम, मेमोरी यानी स्मृति और एम्प्टीनेस यानी ख़ालीपन भी याद कर लीजिए। अब इन शब्दों से अपने वाक्य बनाइए। जैसे द हाउस इज़ फ़ुल ऑफ़ मेमोरीज़, यानी घर यादों से भरा है। और शी फ़ील्ट लोनलीनेस आफ़्टर हर लॉस, यानी नुक़सान के बाद उसे अकेलापन महसूस हुआ।"),
C("🧩","व्याकरण: कंट्रास्ट शब्द",["देन और नाउ","बट, ऑल्दो, हाउएवर","अतीत और वर्तमान की तुलना","भावपूर्ण लेखन में प्रयोग"],"कविता में तब और अब की तुलना है। इसे लिखने के लिए कंट्रास्ट वाले शब्द काम आते हैं, जैसे देन यानी तब, नाउ यानी अब, बट यानी लेकिन और ऑल्दो यानी हालाँकि। जैसे देन द हाउस वाज़ फ़ुल ऑफ़ लव, बट नाउ इट इज़ एम्प्टी, यानी तब घर प्रेम से भरा था, पर अब ख़ाली है। इन शब्दों से आप किसी भी तुलना या स्मृति वाले अनुच्छेद को सुंदर बना सकते हैं। अपने बचपन के किसी घर पर चार वाक्य लिखिए जिनमें देन और नाउ आएँ।"),
C("📌","कविता का सार",["दादी का घर: प्रेम और सुरक्षा","दादी के बाद घर सूना और ठंडा","कवयित्री प्रेम की तलाश में भटकती हैं","संदेश: निःस्वार्थ प्रेम की क़द्र"],"अब कविता का सार दोहरा लें। कमला दास की इस कविता में दादी का घर वह स्थान है जहाँ उन्हें सच्चा प्रेम मिला। दादी के जाने के बाद वह घर सूना और ठंडा हो गया और अब कवयित्री अजनबियों के दरवाज़ों पर प्रेम की तलाश करती हैं। कविता में स्मृति, प्रतीक और आत्मकथात्मक सच्चाई है। संदेश है कि निःस्वार्थ प्रेम सबसे क़ीमती है और हमें अपने अपनों की क़द्र करनी चाहिए। इसे अपने शब्दों में पाँच वाक्यों में लिखकर देखिए।"),
C("❓","संभावित परीक्षा प्रश्न",["कवयित्री का परिचय","कविता का भाव","घर सूना क्यों लगता है","कविता की सीख"],"परीक्षा के प्रश्न देखिए। पहला, कवयित्री का परिचय दीजिए। उत्तर, कमला दास, केरल की, मलयालम में माधवीकुट्टी नाम से भी लेखन, आत्मकथा माई स्टोरी। दूसरा, कविता का भाव? उत्तर, दादी के प्रेम की याद और उसके जाने से बना खालीपन। तीसरा, घर सूना क्यों लगता है? उत्तर, क्योंकि प्रेम करने वाली दादी अब नहीं हैं। चौथा, सीख? उत्तर, निःस्वार्थ प्रेम की क़ीमत समझें और अपनों की क़द्र करें। पूरे वाक्य में उत्तर लिखिए।"),
Q("आपके जीवन में कौन सा स्थान या व्यक्ति कविता की दादी के घर जैसा है? क्यों?","अपना अनुभव लिखिए, जैसे नानी का घर या कोई प्रिय कोना, और बताइए कि वहाँ आपको क्या महसूस होता है।","एक सोचने वाला प्रश्न। आपके जीवन में कौन सा स्थान या व्यक्ति कविता की दादी के घर जैसा है, और क्यों? सोचिए। ... अपना अनुभव लिखिए, जैसे नानी का घर या कोई प्रिय कोना, और बताइए कि वहाँ आपको सुरक्षा और प्रेम कैसे महसूस होता है।"),
],7)
